package review

import (
	"testing"

	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
)

// Repro: budget-trim of the commits list vs the deferred reversal.
func TestRepro_CommitTrimAliasing(t *testing.T) {
	sc := reviewtypes.ScopeContext{
		// newest-first, as git log emits
		Commits: []string{"c5 newest", "c4", "c3", "c2", "c1 oldest"},
	}
	capScopeListsToBudget(&sc, 20) // fits ~2 lines (len+1 each)
	t.Logf("Commits after trim+reverse: %#v truncated=%v", sc.Commits, sc.CommitsTruncated)
	// Expected per doc: keep newest (c5,c4), reversed to oldest-first => ["c4","c5 newest"]
	if len(sc.Commits) != 2 || sc.Commits[1] != "c5 newest" {
		t.Errorf("BUG: got %#v, want newest commits kept oldest-first", sc.Commits)
	}
}

package main

import (
	"fmt"
	"slices"
)

type sc struct {
	Commits          []string
	CommitsTruncated bool
}

// Verbatim logic of capScopeListsToBudget (commits portion only).
func capScopeListsToBudget(s *sc, budget int) {
	defer slices.Reverse(s.Commits)
	if budget <= 0 {
		return
	}
	remaining := budget
	trim := func(lines []string, truncated bool) ([]string, bool) {
		for i, line := range lines {
			cost := len(line) + 1
			if cost > remaining {
				return lines[:i], true
			}
			remaining -= cost
		}
		return lines, truncated
	}
	s.Commits, s.CommitsTruncated = trim(s.Commits, s.CommitsTruncated)
}

func main() {
	s := sc{Commits: []string{"c5 newest", "c4 next", "c3 mid", "c2 old", "c1 oldest"}}
	capScopeListsToBudget(&s, 20) // fits two lines (10 + 8)
	fmt.Printf("result: %#v truncated=%v\n", s.Commits, s.CommitsTruncated)
	fmt.Println("expected (keep-newest, oldest-first): [\"c4 next\", \"c5 newest\"]")
}

